def seed_roles(apps,schema_editor):
    """Create the default roles and attach each existing staff member to the role that matches their current flags
    (unmatched combinations keep working through their flags, with no role)."""
    from shop.permissions import DEFAULT_ROLES
    Role=apps.get_model('shop','Role');Staff=apps.get_model('shop','Staff')
    roles={}
    for code,name,description,perms,discount,refund in DEFAULT_ROLES:
        roles[code],_=Role.objects.get_or_create(code=code,defaults=dict(name=name,description=description,permissions=perms,discount_max_pct=discount,refund_max=refund,system=True))
    for person in Staff.objects.filter(role__isnull=True):
        code=PRESET_BY_FLAGS.get((person.manager,person.can_buy,person.can_sell,person.can_handle_payments))
        if code:
            perms=set(roles[code].permissions)
            Staff.objects.filter(pk=person.pk).update(role=roles[code],manager='manage_branch' in perms,can_buy='buy' in perms,can_sell='sell' in perms,can_handle_payments='payments' in perms)


